-- First detailed anatomical review; preserve all existing exercises and history.
BEGIN;
ALTER TABLE "Exercise" ADD COLUMN IF NOT EXISTS "anatomyReview" JSONB;
DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM "Exercise" WHERE id='b9859cd9-6ed6-4e63-8fd0-500e8cf8d553'
    AND "ownerUserId" IS NULL AND name <> 'Crucifixo na Máquina — aliases: peck deck, pec deck, voador') THEN
    RAISE EXCEPTION 'Peck deck identity changed; review the exercise before applying';
  END IF;
END $$;
UPDATE "Exercise" SET "anatomyReview"='{"version":"2026-10-28.1","reviewedAt":"2026-10-28T00:00:00.000Z","variant":"Peck deck sentado, com encosto e apoios acolchoados nos antebraços; cotovelos flexionados e adução horizontal dos braços.","aliases":["peck deck","pec deck","voador","crucifixo na máquina"],"participants":[{"id":"PECTORALIS_MAJOR","label":"Peitoral maior","muscleGroup":"CHEST","role":"PRIMARY","aliases":["peitoral","peito"],"regions":[{"id":"PECTORALIS_MAJOR_CLAVICULAR","label":"Porção clavicular","aliases":["peitoral superior"]},{"id":"PECTORALIS_MAJOR_STERNOCOSTAL","label":"Porção esternocostal","aliases":["peitoral esternocostal","peitoral médio","peitoral inferior"]}],"emphasizedRegionIds":[],"sourceIds":["ACE_PEC_DECK","MARCHETTI_PEC_DECK"]},{"id":"DELTOID_ANTERIOR","label":"Deltoide anterior","muscleGroup":"SHOULDERS","role":"SECONDARY","aliases":["ombro anterior","deltoide frontal","parte da frente do ombro"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["MARCHETTI_PEC_DECK"]}],"sources":[{"id":"ACE_PEC_DECK","title":"ACE-sponsored chest exercise research and pec deck technique (2012)","url":"https://www.acefitness.org/certifiednews/images/article/pdfs/ACE_BestChestExercises.pdf","limitation":"Relatório de estudo com 14 homens e orientações para a versão com apoios. Não estabelece ênfase regional, percentuais ilustrados nem equivalência de hipertrofia."},{"id":"MARCHETTI_PEC_DECK","title":"Marchetti et al. — rotação do ombro e atividade de peitoral maior/deltoide anterior no pec deck (2019)","url":"https://revistas.icesp.br/index.php/RBPeCS/article/view/733/","limitation":"Estudo isométrico com 10 homens treinados; apoia a participação dos músculos avaliados. Aplicação ao movimento dinâmico e subdivisões anatômicas é inferência, não uma medição direta de todas as regiões."}],"notes":"Peitoral maior como alvo e deltoide anterior como sinergista. Regiões nomeadas pela anatomia do músculo, sem alegar predominância superior/inferior, isolamento ou percentuais de ativação. A lista é ilustrativa e não inclui todo músculo estabilizador. Abertura limitada à linha dos ombros e parâmetros ajustados ao boneco; amplitude e regulagens variam com pessoa e equipamento.","instructions":{"description":"Adução horizontal dos braços na máquina peck deck, com peitoral maior como alvo e deltoide anterior como participante secundário.","setup":"Sente-se com as costas no encosto e pés firmes no chão. Ajuste o assento para apoiar cotovelos e antebraços junto à altura dos ombros, com os cotovelos flexionados.","execution":"Aproxime os apoios à frente do tórax, mantendo a flexão dos cotovelos. Retorne de forma controlada até a abertura confortável, sem levar os braços excessivamente para trás.","tips":"Mantenha o tronco apoiado, ombros sem encolher e a carga sob controle. A amplitude ilustrada depende do ajuste da máquina e não é uma prescrição individual."}}'::jsonb, "updatedAt"=CURRENT_TIMESTAMP
WHERE id='b9859cd9-6ed6-4e63-8fd0-500e8cf8d553' AND "ownerUserId" IS NULL AND "anatomyReview" IS NULL;
COMMIT;
